"""Build detached UI proof. Requires Python Playwright and a Chromium executable."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import os
root=Path(__file__).resolve().parents[3]; out=root/'art/review';out.mkdir(exist_ok=True)
ui=root/'art/ui'
proof='''<!doctype html><html><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}html{background:#070b16}body{margin:0;color:#dff4f5;font-family:Arial,sans-serif;background:radial-gradient(ellipse at 99% 40%,#1f4a6e73,transparent 62%),linear-gradient(160deg,#1b2a44 0%,#0a1424 50%,#070b16);width:390px;height:844px;padding:43px 24px;position:relative;overflow:hidden}body:before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 39px,#dff4f507 39px 40px);pointer-events:none}header,footer,.rail,.section{display:flex;align-items:center;justify-content:space-between}header,.rail,footer,.section,p,article,hr{position:relative}header{font:700 10px monospace;letter-spacing:1.5px;color:#b0c5d5}.tag{border:1px solid #6f899a6e;padding:6px 8px;border-radius:20px;font-size:9px}.title{font:600 37px/1.06 Arial,sans-serif;letter-spacing:-1.9px;margin:36px 0 15px;position:relative}.intro{color:#a9bccb;font-size:14px;line-height:1.52;margin:0 0 32px;max-width:300px}.section{font:700 10px monospace;letter-spacing:1.75px;color:#afc4d7;margin-bottom:12px}.section i{font-style:normal;color:#83a8bd}.glass{background:rgba(10,20,36,.72);backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,.08);border-radius:14px}.lockup{height:120px;display:grid;place-items:center;margin-bottom:30px}.lockup svg{width:120px;height:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.item{height:63px;display:flex;align-items:center;gap:12px;padding:0 14px;font-size:14px;font-weight:600}.item svg,.rail svg{width:24px;height:24px;flex:none}.rail{margin-top:18px;padding:16px 9px;border-top:1px solid #dff4f51c;border-bottom:1px solid #dff4f51c}.rail span{font:9px monospace;letter-spacing:1px;color:#afc4d7}.rail svg{color:#ffb45a}.notes{margin:24px 0 0;color:#a9bccb;font:12px/1.65 Arial}.notes strong{color:#dff4f5}footer{position:absolute;bottom:35px;left:24px;right:24px;font:9px monospace;letter-spacing:1.4px;color:#9bb4c9}
</style><header><span>WAKE / VISUAL SYSTEM</span><span class="tag">GATE 00</span></header><div class="title">Night signals</div><p class="intro">A full-size check of the title mark and trap selectors against the harbor’s night palette.</p><div class="section"><span>01 / WORDMARK</span><i>120 PX</i></div><article class="glass lockup">LOGO</article><div class="section"><span>02 / HAZARD SELECTION</span><i>24 PX</i></div><div class="grid">ICONS</div><div class="rail"><span>SELECTED</span>RAIL</div><p class="notes"><strong>UI contrast proof.</strong> Standalone swatch, not game footage. Final check is over the live scene at gameplay size.</p><footer><span>HARBOR SYSTEMS</span><span>UI STUDY / 01</span></footer></html>'''
names=['searchlight','barge','mine','whirlpool']; icons=[(ui/('icon_'+n+'.svg')).read_text() for n in names]; logo=(ui/'logo.svg').read_text()
proof=proof.replace('LOGO',logo).replace('ICONS',''.join('<article class="glass item">'+ic+n.title()+'</article>' for ic,n in zip(icons,names))).replace('RAIL',''.join(icons))
(out/'ui-night-proof.html').write_text(proof)
with sync_playwright() as p:
 from PIL import Image
 b=p.chromium.launch(executable_path=os.getenv('CHROMIUM','/tmp/chromium'),args=['--no-sandbox','--disable-dev-shm-usage']);pg=b.new_page(viewport={'width':390,'height':844},device_scale_factor=3);pg.set_content(proof)
 dims=pg.locator('.lockup svg,.grid svg').evaluate_all('(a)=>a.map(s=>[s.getBoundingClientRect().width,s.getBoundingClientRect().height])')
 assert dims[0][0]==120 and all(d==[24,24] for d in dims[1:]),dims
 pg.screenshot(path=out/'ui-night-proof.png');b.close()
 im=Image.open(out/'ui-night-proof.png');assert im.size==(1170,2532);im.resize((390,844),Image.Resampling.LANCZOS).save(out/'ui-night-proof-1x.png')
